     1	// Package fidelity holds the intentionally small, provider-independent core of
     2	// the Fidelity intent-versus-implementation verifier.  Keeping it outside cli
     3	// means its policy and orchestration can be tested without executing an Entire
     4	// command or reading a repository.
     5	package fidelity
     6	
     7	import (
     8		"fmt"
     9		"os"
    10		"strconv"
    11		"strings"
    12	)
    13	
    14	// Config is the stable policy seam used by reconciliation.  It deliberately
    15	// describes confidence thresholds rather than claiming that Entire Graph emits
    16	// an extracted/inferred/ambiguous tri-state; graph relations carry numeric
    17	// confidence, resolution, warning codes, and evidence.
    18	type Config struct {
    19		BlastRadiusHops   int
    20		EdgeClasses       EdgeClasses
    21		Extraction        Extraction
    22		ModuleGranularity bool
    23		VerdictThresholds VerdictThresholds
    24		Databricks        Databricks
    25	}
    26	
    27	type EdgeClasses struct {
    28		DeterministicConfidenceGTE float64
    29		AdvisoryBelowConfidence    float64
    30	}
    31	
    32	type Extraction struct {
    33		FallbackLLM         bool
    34		LLMVocabularySource string
    35	}
    36	
    37	type VerdictThresholds struct {
    38		ReviewRequiredIfScopeCreepGTE int
    39	}
    40	
    41	type Databricks struct {
    42		CalibrationEnabled bool
    43		ScoreSource        string
    44		Gate               CalibrationGate
    45		AISearch           AISearch
    46	}
    47	
    48	type CalibrationGate struct {
    49		Mode        string
    50		AlphaTarget float64
    51	}
    52	
    53	type AISearch struct {
    54		Enabled   bool
    55		IndexName string
    56	}
