    58	func DefaultConfig() Config {
    59		return Config{
    60			BlastRadiusHops: 2,
    61			EdgeClasses: EdgeClasses{
    62				DeterministicConfidenceGTE: 0.9,
    63				AdvisoryBelowConfidence:    0.9,
    64			},
    65			Extraction:        Extraction{FallbackLLM: true, LLMVocabularySource: "graph_snapshot"},
    66			ModuleGranularity: true,
    67			VerdictThresholds: VerdictThresholds{ReviewRequiredIfScopeCreepGTE: 1},
    68			Databricks: Databricks{
    69				ScoreSource: "batch",
    70				Gate:        CalibrationGate{Mode: "fallback", AlphaTarget: 0.05},
    71			},
    72		}
    73	}
    74	
    75	// LoadConfig reads Fidelity's deliberately narrow YAML policy file.  The
    76	// parser accepts the scalar/mapping subset used by fidelity.config.yaml and
    77	// rejects unknown keys rather than silently applying a typo as a default.  A
    78	// full YAML dependency is unnecessary until configuration needs YAML features
    79	// such as anchors, multiline scalars, or sequences.
    80	func LoadConfig(path string) (Config, error) {
    81		content, err := os.ReadFile(path)
    82		if err != nil {
    83			return Config{}, fmt.Errorf("read Fidelity config: %w", err)
    84		}
    85		config := DefaultConfig()
    86		section := ""
    87		subsection := ""
    88		for lineNumber, line := range strings.Split(string(content), "\n") {
    89			raw := strings.TrimSpace(strings.SplitN(line, "#", 2)[0])
    90			if raw == "" {
    91				continue
    92			}
    93			indent := len(line) - len(strings.TrimLeft(line, " "))
    94			parts := strings.SplitN(raw, ":", 2)
    95			if len(parts) != 2 {
    96				return Config{}, fmt.Errorf("Fidelity config line %d: expected key: value", lineNumber+1)
    97			}
    98			key := strings.TrimSpace(parts[0])
    99			value := strings.TrimSpace(parts[1])
   100			if value == "" {
   101				switch indent {
   102				case 0:
   103					section, subsection = key, ""
   104				case 2:
   105					subsection = key
   106				default:
   107					return Config{}, fmt.Errorf("Fidelity config line %d: unsupported nesting", lineNumber+1)
   108				}
   109				continue
   110			}
   111			// A scalar at an enclosing indentation level is a sibling of any
   112			// earlier mapping (for example the tiers after expected_blast_radius),
   113			// not a member of that mapping.
   114			if indent == 0 {
   115				section, subsection = "", ""
   116			} else if indent == 2 {
   117				subsection = ""
   118			}
   119			if err := assignConfigValue(&config, section, subsection, key, value); err != nil {
   120				return Config{}, fmt.Errorf("Fidelity config line %d: %w", lineNumber+1, err)
   121			}
   122		}
   123		return config, validateConfig(config)
   124	}
   125	
   126	func assignConfigValue(config *Config, section, subsection, key, value string) error {
   127		value = strings.Trim(value, "\"'")
   128		parseBool := func() (bool, error) { return strconv.ParseBool(value) }
   129		parseInt := func() (int, error) { return strconv.Atoi(value) }
   130		parseFloat := func() (float64, error) { return strconv.ParseFloat(value, 64) }
   131		switch {
   132		case section == "" && key == "blast_radius_hops":
   133			v, err := parseInt()
   134			config.BlastRadiusHops = v
   135			return err
   136		case section == "" && key == "module_granularity":
   137			v, err := parseBool()
   138			config.ModuleGranularity = v
   139			return err
   140		case section == "edge_classes" && key == "deterministic_confidence_gte":
   141			v, err := parseFloat()
   142			config.EdgeClasses.DeterministicConfidenceGTE = v
   143			return err
   144		case section == "edge_classes" && key == "advisory_below_confidence":
   145			v, err := parseFloat()
   146			config.EdgeClasses.AdvisoryBelowConfidence = v
   147			return err
   148		case section == "tiers" && subsection == "" &&
   149			(key == "confirmed" || key == "declared_unimplemented" || key == "undeclared_scope_creep" || key == "advisory_low_confidence"):
   150			if value != "{}" {
   151				return fmt.Errorf("tier %q must be an empty mapping", key)
   152			}
   153			return nil
   154		case section == "tiers" && subsection == "expected_blast_radius" && key == "max_hops":
   155			v, err := parseInt()
   156			if err != nil {
   157				return err
   158			}
   159			if v != config.BlastRadiusHops {
   160				return fmt.Errorf("tiers.expected_blast_radius.max_hops must match blast_radius_hops")
   161			}
   162			return nil
   163		case section == "extraction" && key == "fallback_llm":
   164			v, err := parseBool()
   165			config.Extraction.FallbackLLM = v
   166			return err
   167		case section == "extraction" && key == "llm_vocabulary_source":
   168			config.Extraction.LLMVocabularySource = value
   169			return nil
   170		case section == "verdict_thresholds" && key == "review_required_if_scope_creep_gte":
   171			v, err := parseInt()
   172			config.VerdictThresholds.ReviewRequiredIfScopeCreepGTE = v
   173			return err
   174		case section == "databricks" && subsection == "" && key == "calibration_enabled":
   175			v, err := parseBool()
   176			config.Databricks.CalibrationEnabled = v
   177			return err
   178		case section == "databricks" && subsection == "" && key == "score_source":
   179			config.Databricks.ScoreSource = value
   180			return nil
   181		case section == "databricks" && subsection == "gate" && key == "mode":
   182			config.Databricks.Gate.Mode = value
   183			return nil
   184		case section == "databricks" && subsection == "gate" && key == "alpha_target":
   185			v, err := parseFloat()
   186			config.Databricks.Gate.AlphaTarget = v
   187			return err
   188		case section == "databricks" && subsection == "ai_search" && key == "enabled":
   189			v, err := parseBool()
   190			config.Databricks.AISearch.Enabled = v
   191			return err
   192		case section == "databricks" && subsection == "ai_search" && key == "index_name":
   193			if value != "null" {
   194				config.Databricks.AISearch.IndexName = value
   195			}
   196			return nil
   197		default:
   198			return fmt.Errorf("unknown key %q in %s.%s", key, section, subsection)
   199		}
   200	}
   201	
   202	func validateConfig(config Config) error {
   203		if config.BlastRadiusHops < 1 || config.BlastRadiusHops > 2 {
   204			return fmt.Errorf("blast_radius_hops must be 1 or 2; Entire Graph neighbors supports at most 2")
   205		}
   206		if config.EdgeClasses.DeterministicConfidenceGTE < 0 || config.EdgeClasses.DeterministicConfidenceGTE > 1 ||
   207			config.EdgeClasses.AdvisoryBelowConfidence < 0 || config.EdgeClasses.AdvisoryBelowConfidence > 1 {
   208			return fmt.Errorf("confidence thresholds must be between 0 and 1")
   209		}
   210		if config.Extraction.LLMVocabularySource != "graph_snapshot" {
   211			return fmt.Errorf("llm_vocabulary_source must be graph_snapshot")
   212		}
   213		if config.Databricks.ScoreSource != "batch" && config.Databricks.ScoreSource != "serving_endpoint" {
   214			return fmt.Errorf("score_source must be batch or serving_endpoint")
   215		}
   216		if config.Databricks.Gate.Mode != "fallback" && config.Databricks.Gate.Mode != "icalm_crc" {
   217			return fmt.Errorf("gate.mode must be fallback or icalm_crc")
   218		}
   219		if config.Databricks.Gate.AlphaTarget <= 0 || config.Databricks.Gate.AlphaTarget >= 1 {
   220			return fmt.Errorf("gate.alpha_target must be between 0 and 1")
   221		}
   222		return nil
   223	}
