    63				AdvisoryBelowConfidence:    0.9,
    64			},
    65			Extraction:        Extraction{FallbackLLM: true, LLMVocabularySource: "graph_snapshot"},
    66			ModuleGranularity: true,
    67			VerdictThresholds: VerdictThresholds{ReviewRequiredIfScopeCreepGTE: 1},
    68			Databricks: Databricks{
