   163	
   164	// RunSkeleton is deliberately useful even before transcript access is wired:
   165	// it pins the command's five-stage order and makes the external boundary
   166	// injectable in tests.
   167	func RunSkeleton(ctx context.Context, runner StageRunner, request Request) error {
   168		for _, stage := range []Stage{StageCapture, StageDeclare, StageObserve, StageReconcile, StageManifest} {
   169			if err := runner.RunStage(ctx, stage, request); err != nil {
   170				return fmt.Errorf("Fidelity %s stage: %w", stage, err)
   171			}
   172		}
   173		return nil
   174	}
