════════ preflight.go ════════
     1	package fidelity
     2	
     3	import "github.com/entireio/entire-graph/internal/sem"
     4	
     5	// PreflightReport records the graph facts Fidelity relies on before it attempts
     6	// reconciliation.  It is intentionally derived from the installed provider,
     7	// not copied from the project plan, so a changed provider cannot silently alter
     8	// Fidelity's trust policy.
     9	type PreflightReport struct {
    10		Provider                   string          `json:"provider"`
    11		SchemaVersion              string          `json:"schema_version"`
    12		RelationTypes              map[string]bool `json:"relation_types"`
    13		ConfidenceModel            string          `json:"confidence_model"`
    14		SupportsTwoHopNeighbors    bool            `json:"supports_two_hop_neighbors"`
    15		RequiredRelationsAvailable bool            `json:"required_relations_available"`
    16	}
    17	
    18	// CurrentPreflightReport is the capability portion of Build Map ticket #7.
    19	// Relation evidence itself remains per-snapshot because its availability is
    20	// profile- and language-dependent.
    21	func CurrentPreflightReport() PreflightReport {
    22		capabilities := sem.Capabilities()
    23		relations := make(map[string]bool, len(capabilities.SupportedRelationTypes))
    24		for _, relation := range capabilities.SupportedRelationTypes {
    25			relations[relation] = true
    26		}
    27		return PreflightReport{
    28			Provider:                   capabilities.Provider,
    29			SchemaVersion:              capabilities.SchemaVersion,
    30			RelationTypes:              relations,
    31			ConfidenceModel:            "numeric confidence with resolution, evidence, and warning codes",
    32			SupportsTwoHopNeighbors:    true,
    33			RequiredRelationsAvailable: relations["CALLS"] && relations["DATA_FLOWS"] && relations["TESTS"] && relations["HANDLES_ROUTE"] && relations["HANDLES_GRPC"],
    34		}
    35	}
════════ intent.go ════════
     1	package fidelity
     2	
     3	import (
     4		"sort"
     5		"strings"
     6	)
     7	
     8	// ExtractedEntity is a named intent target. Method and confidence remain part
     9	// of the schema even for deterministic direct mentions so later constrained
    10	// fallback extraction cannot be mistaken for an exact transcript claim.
    11	type ExtractedEntity struct {
    12		Name       string  `json:"name"`
    13		Method     string  `json:"method"`
    14		Confidence float64 `json:"confidence"`
    15	}
    16	
    17	// Intent is Stage 2's provider-independent result. UnresolvedFragments is
    18	// intentionally empty until a constrained fallback is installed; the initial
    19	// direct matcher never invents a symbol for prose it cannot ground.
    20	type Intent struct {
    21		RawText             string            `json:"raw_text"`
    22		ExtractedEntities   []ExtractedEntity `json:"extracted_entities"`
    23		UnresolvedFragments []string          `json:"unresolved_fragments"`
    24		InheritedIntent     bool              `json:"inherited_intent"`
    25		NoBaseline          bool              `json:"no_baseline"`
    26	}
    27	
    28	// FallbackResolver is the only permitted extension point for resolving prose
    29	// that direct graph-grounded matching cannot identify. Implementations receive
    30	// the fragment and the complete allowed vocabulary; they must return either an
    31	// exact vocabulary member or an empty string to abstain.
    32	type FallbackResolver interface {
    33		Resolve(fragment string, vocabulary []string) (name string, confidence float64, err error)
    34	}
    35	
    36	// ResolveFallback fails closed. A model/provider answer outside the supplied
    37	// graph vocabulary is represented as an unresolved fragment, never as an
    38	// invented entity in the manifest.
    39	func ResolveFallback(fragment string, vocabulary []string, resolver FallbackResolver) (ExtractedEntity, string, error) {
    40		if resolver == nil {
    41			return ExtractedEntity{}, fragment, nil
    42		}
    43		name, confidence, err := resolver.Resolve(fragment, vocabulary)
    44		if err != nil {
    45			return ExtractedEntity{}, fragment, err
    46		}
    47		for _, candidate := range vocabulary {
    48			if name == candidate && confidence >= 0 && confidence <= 1 {
    49				return ExtractedEntity{Name: name, Method: "llm_fallback", Confidence: confidence}, "", nil
    50			}
    51		}
    52		return ExtractedEntity{}, fragment, nil
    53	}
    54	
    55	// ExtractDirectMentions finds exact, token-bounded qualified-symbol mentions
    56	// in checkpoint text. This is deliberately conservative: "Verify" is not
    57	// allowed to match "VerifyIntent", and a match is emitted once even when a
    58	// transcript repeats it. Fuzzy matching and LLM fallback belong in later
    59	// tickets because they need an explicit, testable abstention policy.
    60	func ExtractDirectMentions(text string, symbols []Symbol) Intent {
    61		seen := map[string]bool{}
    62		var entities []ExtractedEntity
    63		for _, symbol := range symbols {
    64			name := strings.TrimSpace(symbol.QualifiedName)
    65			if name == "" || seen[name] || !containsSymbolMention(text, name) {
    66				continue
    67			}
    68			seen[name] = true
    69			entities = append(entities, ExtractedEntity{Name: name, Method: "regex", Confidence: 1})
    70		}
    71		sort.Slice(entities, func(i, j int) bool { return entities[i].Name < entities[j].Name })
    72		return Intent{RawText: text, ExtractedEntities: entities, UnresolvedFragments: []string{}}
    73	}
    74	
    75	// DeclareIntent recognizes the deliberately narrow class of follow-up prompts
    76	// that contain no actionable declaration by themselves. When a caller has
    77	// supplied the immediately preceding checkpoint transcript, it can preserve
    78	// the graph-grounded declaration while recording that it was inherited. It
    79	// never silently searches arbitrary older sessions for a plausible claim.
    80	func DeclareIntent(text, baselineText string, symbols []Symbol, noBaseline bool) Intent {
    81		intent := ExtractDirectMentions(text, symbols)
    82		intent.NoBaseline = noBaseline
    83		if len(intent.ExtractedEntities) != 0 || !isVagueFollowUp(text) || baselineText == "" {
    84			return intent
    85		}
    86		inherited := ExtractDirectMentions(baselineText, symbols)
    87		if len(inherited.ExtractedEntities) == 0 {
    88			return intent
    89		}
    90		inherited.RawText = text
    91		inherited.InheritedIntent = true
    92		inherited.NoBaseline = noBaseline
    93		return inherited
    94	}
    95	
    96	func isVagueFollowUp(text string) bool {
    97		normalized := strings.Trim(strings.ToLower(strings.TrimSpace(text)), ".!?")
    98		return normalized == "continue" || normalized == "fix it"
    99	}
   100	
   101	func containsSymbolMention(text, symbol string) bool {
   102		for offset := 0; ; {
   103			index := strings.Index(text[offset:], symbol)
   104			if index < 0 {
   105				return false
   106			}
   107			index += offset
   108			end := index + len(symbol)
   109			beforeOK := index == 0 || !symbolByte(text[index-1])
   110			afterOK := end == len(text) || !symbolByte(text[end]) ||
   111				(text[end] == '.' && (end+1 == len(text) || !symbolByte(text[end+1])))
   112			if beforeOK && afterOK {
   113				return true
   114			}
   115			offset = end
   116		}
   117	}
   118	
   119	func symbolByte(value byte) bool {
   120		return value == '_' || value == '.' ||
   121			(value >= '0' && value <= '9') ||
   122			(value >= 'A' && value <= 'Z') ||
   123			(value >= 'a' && value <= 'z')
   124	}
════════ classify.go ════════
     1	package fidelity
     2	
     3	// EdgeClass is Fidelity's consumer-side trust category. It is derived from
     4	// the provider's numeric confidence and resolution fields; it is not claimed
     5	// to be a native Entire Graph tri-state.
     6	type EdgeClass string
     7	
     8	const (
     9		EdgeDeterministic EdgeClass = "deterministic"
    10		EdgeAdvisory      EdgeClass = "advisory"
    11	)
    12	
    13	type GraphRelation struct {
    14		FromID     string
    15		ToID       string
    16		Type       string
    17		Confidence float64
    18		Resolution string
    19	}
    20	
    21	func ClassifyRelation(relation GraphRelation, config Config) EdgeClass {
    22		if relation.Confidence >= config.EdgeClasses.DeterministicConfidenceGTE &&
    23			(relation.Resolution == "exact" || relation.Resolution == "import_resolved" || relation.Resolution == "package") {
    24			return EdgeDeterministic
    25		}
    26		return EdgeAdvisory
    27	}
════════ reconcile.go ════════
     1	package fidelity
     2	
     3	import "strings"
     4	
     5	type EntityLocation struct {
     6		Entity string `json:"entity"`
     7		File   string `json:"file,omitempty"`
     8		Line   int    `json:"line,omitempty"`
     9	}
    10	
    11	type UnimplementedEntity struct {
    12		Entity string `json:"entity"`
    13		Reason string `json:"reason"`
    14	}
    15	
    16	type DirectReconciliation struct {
    17		Confirmed             []EntityLocation      `json:"confirmed"`
    18		DeclaredUnimplemented []UnimplementedEntity `json:"declared_unimplemented"`
    19	}
    20	
    21	// ReconcileDirectClaims performs the first two deterministic tiers. Matching
    22	// permits a graph diff's short entity name to satisfy a transcript's qualified
    23	// symbol name, but never performs fuzzy equivalence; that remains an explicit
    24	// later policy decision.
    25	func ReconcileDirectClaims(intent Intent, changes []ChangedEntity) DirectReconciliation {
    26		result := DirectReconciliation{
    27			Confirmed:             []EntityLocation{},
    28			DeclaredUnimplemented: []UnimplementedEntity{},
    29		}
    30		for _, claim := range intent.ExtractedEntities {
    31			matched := false
    32			for _, change := range changes {
    33				if !sameEntityName(claim.Name, change.Name) {
    34					continue
    35				}
    36				matched = true
    37				result.Confirmed = append(result.Confirmed, EntityLocation{
    38					Entity: claim.Name, File: change.FilePath, Line: change.StartLine,
    39				})
    40			}
    41			if !matched {
    42				result.DeclaredUnimplemented = append(result.DeclaredUnimplemented, UnimplementedEntity{
    43					Entity: claim.Name, Reason: "named in intent, no matching graph change detected",
    44				})
    45			}
    46		}
    47		return result
    48	}
    49	
    50	func sameEntityName(claim, changed string) bool {
    51		if claim == changed {
    52			return true
    53		}
    54		lastDot := strings.LastIndex(claim, ".")
    55		return lastDot >= 0 && claim[lastDot+1:] == changed
    56	}
════════ pipeline.go ════════
     1	package fidelity
     2	
     3	import (
     4		"context"
     5		"fmt"
     6	)
     7	
     8	// Verification is the structured result produced before renderer-specific
     9	// verdict.json fields are added. Its inputs all pass through Adapter, keeping
    10	// the CLI, parent Entire checkpoint store, and semantic provider separated.
    11	type Verification struct {
    12		CheckpointID     string               `json:"checkpoint_id"`
    13		BaseCheckpointID string               `json:"base_checkpoint_id,omitempty"`
    14		HeadCommit       string               `json:"head_commit"`
    15		BaseCommit       string               `json:"base_commit"`
    16		NoBaseline       bool                 `json:"no_baseline"`
    17		Intent           Intent               `json:"intent"`
    18		Changes          []ChangedEntity      `json:"changes"`
    19		Reconciliation   DirectReconciliation `json:"reconciliation"`
    20	}
    21	
    22	// Pipeline runs the five stable Fidelity stages against a real adapter. A
    23	// StageRunner remains optional instrumentation: it lets callers record or
    24	// render stage progress without allowing those concerns to read external data.
    25	type Pipeline struct {
