    12	)
    13	
    14	// verifyIntentFlags intentionally keeps the command surface small and stable.
    15	type verifyIntentFlags struct {
    16		BaseCheckpointID string
    17		ConfigPath       string
    18		OutputDirectory  string
    19		Repo             string
    20	}
    21	
    22	type verifyIntentResponse struct {
    23		FormatVersion    int                      `json:"format_version"`
    24		Status           string                   `json:"status"`
    25		CheckpointID     string                   `json:"checkpoint_id"`
    26		BaseCheckpointID string                   `json:"base_checkpoint_id,omitempty"`
    27		ConfigPath       string                   `json:"config_path"`
    28		OutputDirectory  string                   `json:"output_directory"`
    29		Stages           []fidelity.Stage         `json:"stages"`
    30		Preflight        fidelity.PreflightReport `json:"preflight"`
    31		Verification     fidelity.Verification    `json:"verification"`
    32		Message          string                   `json:"message"`
    33	}
    34	
    35	func parseVerifyIntentFlags(args []string) (verifyIntentFlags, string, error) {
    36		flags := verifyIntentFlags{ConfigPath: "fidelity.config.yaml", OutputDirectory: "fidelity-out"}
    37		var checkpointID string
    38		for index := 0; index < len(args); index++ {
    39			argument := args[index]
    40			value := func() (string, error) {
    41				index++
    42				if index >= len(args) {
    43					return "", fmt.Errorf("%s requires a value", argument)
    44				}
    45				return args[index], nil
    46			}
    47			var err error
    48			switch argument {
    49			case "--base":
    50				flags.BaseCheckpointID, err = value()
    51			case "--config":
    52				flags.ConfigPath, err = value()
    53			case "--out":
    54				flags.OutputDirectory, err = value()
    55			case "--repo":
    56				flags.Repo, err = value()
    57			default:
    58				if strings.HasPrefix(argument, "-") {
    59					return flags, "", fmt.Errorf("verify-intent received unexpected argument %q", argument)
    60				}
    61				if checkpointID != "" {
    62					return flags, "", fmt.Errorf("verify-intent accepts exactly one checkpoint ID")
    63				}
    64				checkpointID = argument
    65			}
    66			if err != nil {
    67				return flags, "", err
    68			}
    69		}
    70		if checkpointID == "" {
    71			return flags, "", fmt.Errorf("verify-intent requires a checkpoint ID")
    72		}
    73		return flags, checkpointID, nil
    74	}
    75	
    76	type recordingFidelityStages struct{ stages []fidelity.Stage }
    77	
    78	func (runner *recordingFidelityStages) RunStage(_ context.Context, stage fidelity.Stage, _ fidelity.Request) error {
    79		runner.stages = append(runner.stages, stage)
    80		return nil
    81	}
    82	
    83	func runVerifyIntent(ctx context.Context, opts Options, args []string) error {
    84		return runVerifyIntentWithAdapter(ctx, opts, args, fidelity.NativeGraphAdapter{})
    85	}
    86	
    87	func runVerifyIntentWithAdapter(ctx context.Context, opts Options, args []string, adapter fidelity.Adapter) error {
    88		flags, checkpointID, err := parseVerifyIntentFlags(args)
    89		if err != nil {
    90			return err
    91		}
    92		repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
    93		if err != nil {
    94			return err
    95		}
    96		configPath := flags.ConfigPath
    97		if !filepath.IsAbs(configPath) {
    98			configPath = filepath.Join(repo, configPath)
    99		}
   100		config, err := fidelity.LoadConfig(configPath)
   101		if err != nil {
   102			return err
   103		}
   104		runner := &recordingFidelityStages{}
   105		request := fidelity.Request{
   106			CheckpointID: checkpointID, BaseCheckpointID: flags.BaseCheckpointID,
   107			Config: config, OutputDirectory: flags.OutputDirectory,
   108		}
   109		if native, ok := adapter.(fidelity.NativeGraphAdapter); ok && native.Repo == "" {
   110			native.Repo = repo
   111			native.ProviderVersion = opts.Version
   112			adapter = native
   113		}
   114		verification, err := (fidelity.Pipeline{Adapter: adapter, Runner: runner}).Run(ctx, request)
   115		if err != nil {
   116			return err
   117		}
   118		response := verifyIntentResponse{
   119			FormatVersion: 1, Status: "partial", CheckpointID: checkpointID,
   120			BaseCheckpointID: flags.BaseCheckpointID, ConfigPath: configPath,
   121			OutputDirectory: flags.OutputDirectory, Stages: runner.stages,
   122			Preflight:    fidelity.CurrentPreflightReport(),
   123			Verification: verification,
   124			Message:      "transcript capture, graph-grounded declaration, and direct reconciliation are complete; reachability tiers and verdict file rendering are not yet implemented",
   125		}
   126		encoder := json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout))
   127		encoder.SetEscapeHTML(false)
   128		return encoder.Encode(response)
   129	}
