    35	func parseVerifyIntentFlags(args []string) (verifyIntentFlags, string, error) {
    36		flags := verifyIntentFlags{ConfigPath: "fidelity.config.yaml", OutputDirectory: "fidelity-out"}
    37		var checkpointID string
    38		for index := 0; index < len(args); index++ {
    39			argument := args[index]
    40			value := func() (string, error) {
    41				index++
    42				if index >= len(args) {
    43					return "", fmt.Errorf("%s requires a value", argument)
    44				}
    45				return args[index], nil
    46			}
    47			var err error
    48			switch argument {
    49			case "--base":
    50				flags.BaseCheckpointID, err = value()
    51			case "--config":
    52				flags.ConfigPath, err = value()
    53			case "--out":
    54				flags.OutputDirectory, err = value()
    55			case "--repo":
    56				flags.Repo, err = value()
    57			default:
    58				if strings.HasPrefix(argument, "-") {
    59					return flags, "", fmt.Errorf("verify-intent received unexpected argument %q", argument)
    60				}
    61				if checkpointID != "" {
    62					return flags, "", fmt.Errorf("verify-intent accepts exactly one checkpoint ID")
    63				}
    64				checkpointID = argument
    65			}
    66			if err != nil {
    67				return flags, "", err
    68			}
    69		}
    70		if checkpointID == "" {
    71			return flags, "", fmt.Errorf("verify-intent requires a checkpoint ID")
    72		}
    73		return flags, checkpointID, nil
    74	}
