  1	package cli
  2	
  3	import (
  4		"fmt"
  5		"io"
  6		"path/filepath"
  7		"sort"
  8		"strings"
  9	
 10		"github.com/entireio/entire-graph/internal/sem"
 11		"github.com/entireio/entire-graph/internal/termsafe"
 12	)
 13	
 14	// Completeness reporting is a valued feature and is not reduced here — every
 15	// warning and every partial failure stays in the JSON payload, in full. What is
 16	// fixed is the PRESENTATION: an answer about a Rust symbol used to open with
 17	// "degraded ... 273 partial failures" and itemize Python files, which reads as
 18	// "the graph you are about to trust is broken" and pushes a reader back to grep.
 19	//
 20	// A failure is only actionable for a query if it could have removed a fact the
 21	// query would have used. The unit of that relevance the graph actually knows is
 22	// LANGUAGE: relations do not cross language boundaries here, so a Python parse
 23	// error cannot hide a Rust caller. Failures outside the query's language are
 24	// therefore reported as one collapsed line, not itemized, and the headline says
 25	// whether the query's own language is clean.
 26	
 27	// maxScopedDiagnostics caps how many in-scope diagnostics are itemized. In-scope
 28	// failures ARE actionable, so they keep the itemized treatment.
 29	const maxScopedDiagnostics = 3
 30	
 31	// completenessScope is the query-relative view of a snapshot's coverage.
 32	type completenessScope struct {
 33		// Language is the language of the symbol the query is about. Empty means
 34		// the query resolved to nothing, and every diagnostic is then in scope.
 35		Language string `json:"language,omitempty"`
 36		// LanguageFiles / LanguageParsed count files of that language.
 37		LanguageFiles  int `json:"language_files,omitempty"`
 38		LanguageFailed int `json:"language_failed_files,omitempty"`
 39		// OtherFailures is the number of partial failures in other languages, with
 40		// the languages named for auditability.
 41		OtherFailures  int      `json:"other_language_failures,omitempty"`
 42		OtherLanguages []string `json:"other_failure_languages,omitempty"`
 43		// InScope are the diagnostics that can affect this query's answer.
 44		InScopeWarnings []sem.ProviderWarning `json:"in_scope_warnings,omitempty"`
 45		InScopeFailures []sem.PartialFailure  `json:"in_scope_failures,omitempty"`
 46		// Worktree records that the snapshot came from the working tree. That is
 47		// provenance, not lost coverage, so it no longer degrades the headline.
 48		Worktree bool `json:"worktree_snapshot,omitempty"`
 49		// Level is the snapshot's own completeness level, carried through unchanged.
 50		Level string `json:"level,omitempty"`
 51	}
 52	
 53	// worktreeProvenanceWarning is the code the provider emits to say a snapshot was
 54	// read from the working tree rather than a commit. It reports WHICH tree was
 55	// read, not that anything failed to parse, so it is presented as provenance.
 56	const worktreeProvenanceWarning = "W_WORKTREE_SNAPSHOT"
 57	
 58	// buildCompletenessScope partitions a snapshot's diagnostics by whether they can
 59	// affect a query about queryLanguage.
 60	func buildCompletenessScope(snapshot sem.ProviderSnapshot, queryLanguage string) completenessScope {
 61		scope := completenessScope{Language: queryLanguage, Level: snapshot.Header.Stats.CompletenessLevel}
 62		if language, ok := snapshot.Header.Completeness.Languages[queryLanguage]; ok {
 63			scope.LanguageFiles = language.Files
 64		}
 65		languageByPath := make(map[string]string, len(snapshot.Files))
 66		for _, file := range snapshot.Files {
 67			languageByPath[filepath.ToSlash(file.Path)] = file.Language
 68		}
 69		otherLanguages := map[string]int{}
 70		for _, failure := range snapshot.Header.PartialFailures {
 71			language := languageByPath[filepath.ToSlash(failure.FilePath)]
 72			if diagnosticInScope(queryLanguage, language, failure.FilePath) {
 73				scope.LanguageFailed++
 74				if len(scope.InScopeFailures) < maxScopedDiagnostics {
 75					scope.InScopeFailures = append(scope.InScopeFailures, failure)
 76				}
 77				continue
 78			}
 79			scope.OtherFailures++
 80			if language == "" {
 81				language = "unknown"
 82			}
 83			otherLanguages[language]++
 84		}
 85		for _, warning := range snapshot.Header.Warnings {
 86			if warning.Code == worktreeProvenanceWarning {
 87				scope.Worktree = true
 88				continue
 89			}
 90			language := languageByPath[filepath.ToSlash(warning.FilePath)]
