107	// diagnosticInScope decides whether a diagnostic can affect an answer about
108	// queryLanguage. With no query language, or a diagnostic with no file (a
109	// repository-wide condition), everything is in scope — the safe direction.
110	func diagnosticInScope(queryLanguage, fileLanguage, filePath string) bool {
111		if queryLanguage == "" || filePath == "" {
112			return true
113		}
114		if fileLanguage == "" {
115			// The file is not in the snapshot's file records: its language is
116			// unknown, so it cannot be ruled out.
117			return true
118		}
119		return strings.EqualFold(fileLanguage, queryLanguage)
120	}
