122	// rankedLanguageNames renders "Python 271, JSON 2" style breakdowns, most
123	// failures first, capped so the collapsed line stays one line.
124	func rankedLanguageNames(counts map[string]int) []string {
125		names := make([]string, 0, len(counts))
126		for name := range counts {
127			names = append(names, name)
128		}
129		sort.Slice(names, func(left, right int) bool {
130			if counts[names[left]] != counts[names[right]] {
131				return counts[names[left]] > counts[names[right]]
132			}
133			return names[left] < names[right]
134		})
135		if len(names) > 3 {
136			names = names[:3]
137		}
138		rendered := make([]string, 0, len(names))
139		for _, name := range names {
140			rendered = append(rendered, fmt.Sprintf("%s %d", name, counts[name]))
141		}
142		return rendered
143	}
