146	//
147	// Silent when there is nothing to say. One line when nothing is actionable for
148	// this query. Itemized only for diagnostics that could actually have removed a
149	// fact the query needed.
150	func writeScopedCompletenessBlock(
151		out io.Writer,
152		scope completenessScope,
153		warnings []sem.ProviderWarning,
154		partialFailures []sem.PartialFailure,
155		stats sem.ProviderStats,
156	) {
