158		if !actionable && scope.OtherFailures == 0 &&
159			(stats.CompletenessLevel == "" || stats.CompletenessLevel == "ok") {
160			return
161		}
162		if !actionable {
163			// Nothing in this query's scope failed. Say exactly that, in one line,
164			// and keep the honest total plus a pointer to the full list.
165			if scope.OtherFailures == 0 {
166				return
167			}
168			fmt.Fprintf(out, "Completeness: no parse failures in %s (%s); %d elsewhere (%s) cannot affect this answer — see --format json.\n",
