170				scope.OtherFailures, strings.Join(scope.OtherLanguages, ", "),
171			)
172			return
173		}
174		level := stats.CompletenessLevel
175		if level == "" {
176			level = "degraded"
177		}
178		// A FRACTION only when the denominator is real. `LanguageFiles` counts files that parsed, so a
179		// language whose files all failed reports 0 — and "35 of 0 files failed to parse" (three.js),
180		// "6 of 0" (terraform) is not a small error, it is a number that cannot be true and it discredits
181		// every other count on the line. When the denominator is missing or smaller than the numerator, the
182		// honest form is the count alone.
183		total := len(warnings) + len(partialFailures)
184		if scope.LanguageFiles <= 0 || scope.LanguageFailed > scope.LanguageFiles {
185			fmt.Fprintf(out, "Completeness: %s for %s (%d %s file%s failed to parse; %d total diagnostic%s in this snapshot)\n",
