		wantSuffix := " | " + itoaForTest(want) + " |"
		if !strings.Contains(markdown, tier) {
			t.Fatalf("markdown missing tier %q entirely", tier)
		}
		lineStart := strings.Index(markdown, "| "+tier+" |")
		if lineStart < 0 {
			t.Fatalf("markdown table row for %q not found", tier)
		}
		lineEnd := strings.Index(markdown[lineStart:], "\n")
		line := markdown[lineStart : lineStart+lineEnd]
		if !strings.HasSuffix(strings.TrimRight(line, " "), wantSuffix) {
			t.Fatalf("markdown row for %q = %q, want count %d", tier, line, want)
		}
	}
	// Every rendered tier must also carry the terminal count summary line's
	// total, which is the same verdict summary both renderers read from.
	if !strings.Contains(terminal, itoaForTest(verdict.Summary.TotalChangedEntities)+" changed entities") {
		t.Fatalf("terminal output does not report the verdict's own total_changed_entities: %s", terminal)
	}
}

func itoaForTest(n int) string {
	if n == 0 {
		return "0"
	}
	digits := ""
	for n > 0 {
		digits = string(rune('0'+n%10)) + digits
		n /= 10
	}
	return digits
}

