1	package fidelity
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"html/template"
8	)
9	
10	// dashboard.go implements #40: dashboard.html, three-way-aware from the
11	// start. Per the user's explicit design choices: a tier-grouped summary tab
12	// (default) plus a Graph View tab for the entities that actually carry real
13	// path/edge data (expected_blast_radius), and verdict.json's content
14	// embedded inline at generation time rather than fetch()ed at runtime — no
15	// server, no CORS, opens by double-click. A pure function of Verdict, like
16	// every other renderer; no adapter or repo access.
17	//
18	// The Graph View draws an edge ONLY where a real path_from_confirmed exists
19	// (expected_blast_radius). Advisory/scope-creep/unverifiable-coverage nodes
20	// are placed and colored by tier but never connected by a fabricated edge —
21	// consistent with the whole project's refusal to present an absent
22	// relationship as a real one.
23	
24	func RenderDashboard(verdict Verdict) (string, error) {
25		verdictJSON, err := json.Marshal(verdict)
26		if err != nil {
27			return "", fmt.Errorf("encode verdict for dashboard: %w", err)
28		}
29		graphNodes, graphEdges := dashboardGraph(verdict)
30		nodesJSON, err := json.Marshal(graphNodes)
31		if err != nil {
32			return "", fmt.Errorf("encode dashboard graph nodes: %w", err)
33		}
34		edgesJSON, err := json.Marshal(graphEdges)
35		if err != nil {
36			return "", fmt.Errorf("encode dashboard graph edges: %w", err)
37		}
38	
39		data := dashboardTemplateData{
40			VerdictJSON:    template.JS(verdictJSON),
41			GraphNodes:     template.JS(nodesJSON),
42			GraphEdges:     template.JS(edgesJSON),
43			CheckpointID:   verdict.CheckpointID,
44			VerdictLabel:   verdict.Summary.VerdictLabel,
45			LabelConfirmed: labelConfirmed, LabelHeuristic: labelHeuristic,
46			LabelUnverifiable: labelUnverifiable, LabelDrift: labelDrift,
47			ConfirmedCount:    len(verdict.Reconciliation.Confirmed) + len(verdict.Reconciliation.ExpectedBlastRadius),
48			HeuristicCount:    len(verdict.Reconciliation.AdvisoryLowConfidence),
49			UnverifiableCount: len(verdict.Reconciliation.UnverifiableCoverage),
50			DriftCount:        len(verdict.Reconciliation.UndeclaredScopeCreep) + len(verdict.Reconciliation.DeclaredUnimplemented),
51		}
52		var out bytes.Buffer
53		if err := dashboardTemplate.Execute(&out, data); err != nil {
54			return "", fmt.Errorf("render dashboard: %w", err)
55		}
56		return out.String(), nil
57	}
58	
59	type dashboardNode struct {
60		ID    string `json:"id"`
61		Label string `json:"label"`
62		Tier  string `json:"tier"`  // one of the four visual categories
63		Color string `json:"color"` // matches the terminal/Markdown renderer palette
64	}
65	
66	type dashboardEdge struct {
67		Source string `json:"source"`
68		Target string `json:"target"`
69		Type   string `json:"type"`
70	}
71	
72	const (
73		colorConfirmed    = "#3fb950"
74		colorHeuristic    = "#d29922"
75		colorUnverifiable = "#bc8cff"
76		colorDrift        = "#f85149"
77	)
78	
79	// dashboardGraph builds the Graph View's nodes/edges. Real edges exist only
80	// for expected_blast_radius (the only tier carrying path_from_confirmed);
81	// every other tier contributes unconnected, tier-colored nodes.
82	func dashboardGraph(verdict Verdict) ([]dashboardNode, []dashboardEdge) {
83		var nodes []dashboardNode
84		var edges []dashboardEdge
85		seen := map[string]bool{}
86		addNode := func(id, label, tier, color string) {
87			if id == "" || seen[id] {
88				return
89			}
90			seen[id] = true
91			nodes = append(nodes, dashboardNode{ID: id, Label: label, Tier: tier, Color: color})
92		}
93	
94		for _, entry := range verdict.Reconciliation.Confirmed {
95			addNode(entry.Entity, entry.Entity, "confirmed", colorConfirmed)
96		}
97		for _, entry := range verdict.Reconciliation.ExpectedBlastRadius {
98			// The path's own last element IS this entity's graph symbol ID
99			// (reachability.go appends the target itself), so labeling it with
100			// entry.Entity (the diff's short name) instead of the same
101			// lastSegment used for every other path node would silently create
102			// two disconnected nodes for one entity. Use the path consistently.
103			if len(entry.PathFromConfirmed) == 0 {
104				addNode(entry.Entity, entry.Entity, "expected_blast_radius", colorConfirmed)
105				continue
106			}
107			for i := 0; i < len(entry.PathFromConfirmed)-1; i++ {
108				from, to := lastSegment(entry.PathFromConfirmed[i]), lastSegment(entry.PathFromConfirmed[i+1])
109				fromTier, toTier := "confirmed", "confirmed"
110				if i+1 == len(entry.PathFromConfirmed)-1 {
111					toTier = "expected_blast_radius"
112				}
113				addNode(from, from, fromTier, colorConfirmed)
114				addNode(to, to, toTier, colorConfirmed)
115				edgeType := ""
116				if i < len(entry.EdgeTypesTraversed) {
117					edgeType = entry.EdgeTypesTraversed[i]
118				}
119				edges = append(edges, dashboardEdge{Source: from, Target: to, Type: edgeType})
120			}
121		}
122		for _, entry := range verdict.Reconciliation.AdvisoryLowConfidence {
123			addNode(entry.Entity, entry.Entity, "advisory_low_confidence", colorHeuristic)
124		}
125		for _, entry := range verdict.Reconciliation.UnverifiableCoverage {
126			addNode(entry.Entity, entry.Entity, "unverifiable_coverage", colorUnverifiable)
127		}
128		for _, entry := range verdict.Reconciliation.UndeclaredScopeCreep {
129			addNode(entry.Entity, entry.Entity, "undeclared_scope_creep", colorDrift)
130		}
131		if nodes == nil {
132			nodes = []dashboardNode{}
133		}
134		if edges == nil {
135			edges = []dashboardEdge{}
136		}
137		return nodes, edges
138	}
139	
140	// lastSegment reads a compound symbol ID the one positionally-safe way
141	// snapshot-format.md documents for a trailing field: anchor on the LAST
142	// separator. It is a display label, not an identity.
143	func lastSegment(id string) string {
144		for i := len(id) - 1; i >= 0; i-- {
145			if id[i] == ':' {
146				return id[i+1:]
147			}
148		}
149		return id
150	}
151	
